/**
 * Sorts an array of objects by a specified key.
 *
 * @param {Array<Object>} arr The array of objects to sort.
 * @param {string} key The key in the objects to sort by.
 * @param {string} [order='asc'] The sorting order: 'asc' for ascending, 'desc' for descending.
 * @returns {Array<Object>} A new array containing the sorted objects.
 * @throws {Error} If the provided array is not an array or the key is not found in the objects.
 */
function sortArrayOfObjectsByKey(arr, key, order = 'asc') {
    if (!Array.isArray(arr)) {
        throw new Error("The first argument must be an array.");
    }

    if (!key) {
        throw new Error("The key to sort by cannot be empty.");
    }

    // Create a copy of the array to avoid mutating the original array
    const sortedArr = [...arr];

    sortedArr.sort((a, b) => {
        const valA = a[key];
        const valB = b[key];

        // Handle cases where the values might be missing or not comparable (e.g., null, undefined)
        if (valA === undefined || valB === undefined) {
            // Decide how to handle missing values. Here, we treat undefined as smaller.
            if (valA === undefined && valB !== undefined) return order === 'asc' ? -1 : 1;
            if (valA !== undefined && valB === undefined) return order === 'asc' ? 1 : -1;
            return 0; // Both undefined or both present (but we handle the comparison below)
        }

        // Standard comparison logic for strings and numbers
        if (typeof valA === 'string' && typeof valB === 'string') {
            const comparison = valA.localeCompare(valB);
            return order === 'asc' ? comparison : -comparison;
        }

        if (valA < valB) {
            return order === 'asc' ? -1 : 1;
        }
        if (valA > valB) {
