### 1. Iterative Approach (Recommended)

This approach uses dynamic programming principles to calculate the numbers iteratively, which is much more efficient (O(n) time complexity and O(1) space complexity if we only store the last two numbers).

```typescript
/**
 * Calculates the n-th Fibonacci number iteratively.
 * The sequence starts with F(0) = 0 and F(1) = 1.
 *
 * @param n The index of the Fibonacci number to calculate (must be a non-negative integer).
 * @returns The n-th Fibonacci number.
 * @throws {Error} If n is negative.
 */
function fibonacciIterative(n: number): number {
    if (n < 0) {
        throw new Error("Input must be a non-negative integer.");
    }
    if (n === 0) {
        return 0;
    }
    if (n === 1) {
        return 1;
    }

    let a: number = 0; // Represents F(i-2)
    let b: number = 1; // Represents F(i-1)
    let result: number = 0;

    // Start loop from i = 2 up to n
    for (let i = 2; i <= n; i++) {
        result = a + b;
        // Shift the values for the next iteration
        a = b;
        b = result;
    }

    return result;
}

// Example Usage:
