console.log("Unique Numbers:", uniqueNumbers); // Output: [1, 2, 3, 4, 5]

console.log("--------------------");

// Example 2: Array of strings
const wordsWithDuplicates: string[] = ["apple", "banana", "apple", "orange", "banana"];
const uniqueWords: string[] = removeDuplicates(wordsWithDuplicates);
console.log("Original Words:", wordsWithDuplicates);
console.log("Unique Words:", uniqueWords); // Output: ["apple", "banana", "orange"]

console.log("--------------------");

// Example 3: Array with mixed types (if T is defined broadly, though usually T is specific)
// Note: This works well for primitives. For complex objects, Set relies on reference equality.
interface User {
    id: number;
    name: string;
}

const users: User[] = [
    { id: 1, name: "Alice" },
    { id: 2, name: "Bob" },
    { id: 1, name: "Alice" } // Duplicate based on object reference if we were using a Map/Set of objects directly
];

// For objects, the Set will treat two distinct objects with the same content as unique unless they are the exact same reference.
// If you need to deduplicate objects based on a specific property (like 'id'), you would use a Map or filter:
const uniqueUsersById: User[] = Array.from(new Map(users.map(user => [user.id, user])).values());
console.log("Unique Users by ID:", uniqueUsersById);
```

### Explanation:

1.  **Generics (`<T>`):** The function is made generic using `<T>`. This means the function can work with an array of *any* type (`number[]`, `string[]`, `User[]`, etc.) while maintaining type safety.
2.  **`new Set(arr)`:** A `Set` is a built-in JavaScript data structure that only allows unique values. When you pass an array to the `Set` constructor, it automatically iterates over the array and discards any duplicate entries.
3.  **`[... ]` (Spread Syntax):** The `Set` object itself is not an array. We use the spread syntax (`...`) to unpack all the unique elements from the `Set` and place them into a new array, which is then returned

Here is a TypeScript function to debounce another function. This implementation uses a closure to maintain a timer ID and ensures that the function is only executed after a specified delay has passed without any further calls.

```typescript
/**
 * Creates a debounced version of the provided function.
 * The debounced function will only execute after a specified delay has passed
 * since the last time it was invoked.
 *
 * @param func The function to debounce.
 * @param delay The number of milliseconds to wait after the last invocation before executing func.
 * @returns A new function that is the debounced version of the input function.
 */
function debounce<T extends (...args: any[]) => any>(
  func: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  return function(this: ThisParameterType<T>, ...args: Parameters<T>): void {
    // Clear the previous timeout if it exists
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // Set a new timeout
    timeoutId = setTimeout(() => {
      // Execute the original function with the correct context and arguments
      func.apply(this, args);
      timeoutId = null; // Clear the timeout ID after execution
    }, delay);
  };
}

// --- Example Usage ---

// 1. The function we want to debounce
const logInput = (text: string): void => {
  console.log(`API call triggered with: ${text}`);
};

// 2. Create the debounced version, waiting 500ms
const debouncedLog = debounce(logInput, 500);

console.log("Simulating rapid input...");

// Simulate rapid calls
debouncedLog("a");
debouncedLog("ab");
debouncedLog("abc");

// Wait 1 second, then call again
setTimeout(() => {
  debouncedLog("abcd");
}, 1000);

// Wait another 1 second
setTimeout(() => {
  debouncedLog("abcde");
}, 2000);

// After 2.5 seconds, only the last call ("abcde") will execute after the 500ms delay.
```

### Explanation:

1.  **Generics (`<T extends (...args: any[]) => any>`):**
    *   This makes the `debounce` function generic. It ensures that the function passed to it (`func`) is a valid function.
    *   `T` represents the type of the original function.

2.  **Closure Variable (`let timeoutId: ...`):**
    *   `timeoutId` is declared in the outer scope of `debounce`. This variable is accessible and mutable by the returned function, creating a closure. It stores the ID returned by `setTimeout`.

3.  **The Returned Function:**
    *   `return function(this: ThisParameterType<T>, ...args: Parameters<T>): void { ... }`
    *   This is the function that the user will call repeatedly. It accepts any arguments (`...args`) and preserves the `this` context (`this: ThisParameterType<T>`) of the call.

4.  **Debouncing Logic:**
    *   `if (timeoutId !== null) { clearTimeout(timeoutId); }`: This is the core of debouncing. Every time the debounced function is called, it immediately cancels any previously scheduled execution

Here is a TypeScript function that merges two sorted arrays into a single sorted array.

This implementation uses the standard two-pointer approach, which is efficient with a time complexity of $O(n+m)$, where $n$ and $m$ are the lengths of the two arrays.

```typescript
/**
 * Merges two sorted arrays into a single sorted array.
 *
 * @param arr1 The first sorted array.
 * @param arr2 The second sorted array.
 * @returns A new array containing all elements from arr1 and arr2, sorted in ascending order.
 */
function mergeSortedArrays<T>(arr1: T[], arr2: T[]): T[] {
    const mergedArray: T[] = [];
    let i = 0; // Pointer for arr1
    let j = 0; // Pointer for arr2

    // While both arrays have elements to compare
    while (i < arr1.length && j < arr2.length) {
        if (arr1[i] <= arr2[j]) {
            mergedArray.push(arr1[i]);
            i++;
        } else {
            mergedArray.push(arr2[j]);
            j++;
        }
    }

    // Add any remaining elements from arr1 (if any)
    while (i < arr1.length) {
        mergedArray.push(arr1[i]);
        i++;
    }

    // Add any remaining elements from arr2 (if any)
    while (j < arr2.length) {
        mergedArray.push(arr2[j]);
        j++;
    }

    return mergedArray;
}

// --- Example Usage ---

// Example 1: Merging arrays of numbers
const sortedNumbers1: number[] = [1, 3, 5, 7];
const sortedNumbers2: number[] = [2, 4, 6, 8, 10];
const mergedNumbers: number[] = mergeSortedArrays(sortedNumbers1, sortedNumbers2);

console.log("Merged Numbers:", mergedNumbers); // Output: [1, 2, 3, 4, 5, 6, 7, 8, 10]

// Example 2: Merging arrays of strings
const sortedStrings1: string[] = ["apple", "banana", "cherry"];
const sortedStrings2: string[] = ["apricot", "date", "fig"];
const mergedStrings: string[] = mergeSortedArrays(sortedStrings1, sortedStrings2);

console.log("Merged Strings:", mergedStrings); // Output: ["apple", "apricot", "banana", "cherry", "date", "fig"]

// Example 3: Merging with empty arrays
const arrA: boolean[] = [true, false];
const arrB: boolean[] = [];
const mergedEmpty: boolean[] = mergeSortedArrays(arrA, arrB);

console.log("Merged with Empty Array:", mergedEmpty); // Output: [false, true]
```

Here is a TypeScript function that counts the words in a given string.

This implementation handles various forms of whitespace (spaces, tabs, newlines) by splitting the string based on any sequence of whitespace characters and then filtering out any empty strings that might result from leading/trailing whitespace.

```typescript
/**
 * Counts the number of words in a given string.
 * Words are defined as sequences of non-whitespace characters separated by whitespace.
 *
 * @param text The input string to analyze.
 * @returns The number of words in the string. Returns 0 if the input is null, undefined, or an empty string.
 */
function countWords(text: string | null | undefined): number {
  if (!text) {
    return 0;
  }

  // 1. Trim the string to remove leading/trailing whitespace.
  const trimmedText = text.trim();

  // 2. If the string is empty after trimming, there are no words.
  if (trimmedText.length === 0) {
    return 0;
  }

  // 3. Split the string by one or more whitespace characters (\s+).
  // This handles spaces, tabs, and newlines correctly.
  const words: string[] = trimmedText.split(/\s+/);

  // 4. Return the length of the resulting array.
  return words.length;
}

// --- Examples ---

console.log(`"Hello world": ${countWords("Hello world")}`); // Output: 2
console.log(`"  leading and trailing spaces  ": ${countWords("  leading and trailing spaces  ")}`); // Output: 4
console.log(`"Multiple   spaces   here": ${countWords("Multiple   spaces   here")}`); // Output: 3
console.log(`"": ${countWords("")}`); // Output: 0
console.log(`" \t\n ": ${countWords(" \t\n ")}`); // Output: 0
console.log(`null: ${countWords(null as any)}`); // Output: 0
console.log(`undefined: ${countWords(undefined as any)}`); // Output: 0
console.log(`"One\nTwo\tThree": ${countWords("One\nTwo\tThree")}`); // Output: 3
```

Here is a TypeScript function that fetches JSON data from a given URL and returns the parsed JSON object.

This solution uses the modern `fetch` API and includes proper error handling for network issues or non-successful HTTP responses.

```typescript
/**
 * Fetches JSON data from a specified URL and returns the parsed JSON object.
 *
 * @param url The URL from which to fetch the data.
 * @returns A Promise that resolves with the parsed JSON data.
 * @throws An error if the network request fails or the response status is not OK (200-299).
 */
async function fetchJsonData(url: string): Promise<any> {
  try {
    // 1. Perform the network request
    const response = await fetch(url);

    // 2. Check if the response status is OK (status code 200-299)
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status} for URL: ${url}`);
    }

    // 3. Parse the response body as JSON
    const data: any = await response.json();

    return data;
  } catch (error) {
    // 4. Handle any errors (network errors, JSON parsing errors, or errors thrown above)
    console.error(`Failed to fetch JSON from ${url}:`, error);
    // Re-throw the error so the caller can handle it
    throw error;
  }
}

// --- Example Usage ---

