/**
 * Defines the structure for the objects in the array.
 * You can change this interface to match your actual data structure.
 */
interface DataItem {
  id: number;
  category: string;
  value: number;
}

/**
 * Groups an array of objects by the value of a specified key.
 *
 * @param arr The array of objects to group.
 * @param key The key in the objects to group by.
 * @returns A Map where keys are the unique values of the grouping key,
 *          and values are arrays of objects belonging to that group.
 */
function groupBy<T extends Record<string, any>, K extends keyof T>(
  arr: T[],
  key: K
): Map<T[K], T[]> {
  return arr.reduce((acc: Map<T[K], T[]>, item: T): Map<T[K], T[]> => {
    // Get the value of the grouping key for the current item
    const groupKey: T[K] = item[key];

    // Check if the accumulator already has an array for this key
    if (!acc.has(groupKey)) {
      // If not, initialize it with an array containing the current item
      acc.set(groupKey, [item]);
    } else {
      // If it exists, push the current item to the existing array
      const existingArray: T[] = acc.get(groupKey)!;
      existingArray.push(item);
      acc.set(groupKey, existingArray);
    }

    return acc;
  }, new Map<T[K], T[]>());
}

