Here is a TypeScript function that converts a snake\_case string to camelCase.

This implementation handles cases where the input might start with an uppercase letter (like in PascalCase or if the first word is capitalized) by ensuring the very first word remains lowercase, which is the standard for camelCase.

```typescript
/**
 * Converts a snake_case string to camelCase.
 *
 * @param snakeCaseString The input string in snake_case format (e.g., "hello_world_example").
 * @returns The converted string in camelCase format (e.g., "helloWorldExample").
 */
function snakeToCamel(snakeCaseString: string): string {
  if (!snakeCaseString) {
    return "";
  }

  // Split the string by the underscore character
  const parts: string[] = snakeCaseString.split('_');

  if (parts.length === 0) {
    return "";
  }

  // The first part remains as is (or lowercased if we strictly enforce camelCase start)
  let camelCaseString: string = parts[0];

  // Iterate over the rest of the parts and capitalize the first letter of each
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    if (part.length > 0) {
      // Capitalize the first letter and append the rest of the string in lowercase
      const capitalizedPart = part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
      camelCaseString += capitalizedPart;
    }
  }

  return camelCaseString;
}

// --- Examples ---

