Here is a C function that copies a string without using `strcpy`. This implementation manually iterates through the source string and copies each character to the destination buffer, ensuring null termination.

```c
#include <stdio.h>
#include <string.h> // Included for strlen, though not strictly needed for the copy logic itself

/**
 * @brief Copies a string from a source buffer to a destination buffer without using strcpy.
 *
 * @param destination The buffer where the string will be copied to.
 * @param source The string to be copied from.
 * @return int Returns 0 on success, or -1 if the destination buffer is too small
 *             to hold the entire source string plus the null terminator.
 */
int custom_strncpy(char *destination, const char *source) {
    if (destination == NULL || source == NULL) {
        return -1; // Handle null pointers
    }

    int i = 0;
    // Iterate through the source string until the null terminator is found
    while (source[i] != '\0') {
        destination[i] = source[i];
        i++;
    }

    // Crucially, manually add the null terminator to the destination string
    destination[i] = '\0';

    return 0; // Success
}

// Example usage:
int main() {
    char source[] = "Hello, World!";
    // Destination buffer must be large enough (size of source + 1 for null terminator)
    char destination[50];

    printf("Source string: \"%s\"\n", source);

    if (custom_strncpy(destination, source) == 0) {
        printf("Copy successful.\n");
        printf("Destination string: \"%s\"\n", destination);
    } else {
        printf("Copy failed (buffer too small or invalid input).\n");
    }

    // Example of a potential failure case (buffer too small)
    char small_dest[5];
    printf("\nTesting buffer overflow scenario:\n");
    if (custom_strncpy(small_dest, source) != 0) {
        printf("Copy correctly failed for small buffer.\n");
    } else {
        printf("Copy succeeded unexpectedly for small buffer.\n");
    }

    return 0;
}
```

### Explanation of the Logic:

1.  **Input Validation:** The function first checks if either the `destination` or `source` pointers are `NULL`. If so, it returns an error code (`-1`).
2.  **Initialization:** An index variable `i` is initialized to `0`. This index will track the current position in both the source and destination strings.
3.  **Iteration:** A `while` loop continues as long as the character at the current index `i` in the `source` string is *not* the null terminator (`\0`).
4.  **Copying:** Inside the loop, the character from `source[i]` is copied directly to `destination[i]`.
5.  **Increment:** The index `i` is incremented to move to the next character.
6.  **Null Termination:** After the loop finishes (meaning we have copied all characters up to, but not including, the null terminator of the source), we explicitly set `destination[i] = '\0';`. This is the most critical step to ensure the destination is a valid C-style string.
7.  **Return Value:** The function returns `0` to indicate successful completion.

Here is a C function that sorts an integer array using the bubble sort algorithm.

```c
#include <stdio.h>

/**
 * @brief Sorts an integer array using the bubble sort algorithm.
 *
 * @param arr The integer array to be sorted.
 * @param n The number of elements in the array.
 */
void bubbleSort(int arr[], int n) {
    int i, j;
    int swapped;

    // Outer loop for passes
    for (i = 0; i < n - 1; i++) {
        swapped = 0; // Flag to optimize: if no two elements were swapped by inner loop, then the array is sorted.

        // Inner loop for comparisons and swaps
        // The last i elements are already in place, so we only need to check up to n - 1 - i
        for (j = 0; j < n - 1 - i; j++) {
            // Compare adjacent elements
            if (arr[j] > arr[j + 1]) {
                // Swap arr[j] and arr[j+1]
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = 1;
            }
        }

        // If no two elements were swapped by inner loop, then break
        if (swapped == 0) {
            break;
        }
    }
}

// Example usage:
int main() {
    int numbers[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(numbers) / sizeof(numbers[0]);

    printf("Original array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");

    bubbleSort(numbers, n);

    printf("Sorted array:   ");
    for (int i = 0; i < n; i++) {
        printf("%d ", numbers[i]);
    }
    printf("\n");

    return 0;
}
```

