```rust
/// Checks if a given string is a palindrome.
///
/// The check is case-insensitive and ignores non-alphanumeric characters.
///
/// # Arguments
///
/// * `s` - The string slice to check.
///
/// # Returns
///
/// `true` if the string is a palindrome, `false` otherwise.
pub fn is_palindrome(s: &str) -> bool {
    // 1. Filter and normalize the string:
    //    - Convert to lowercase.
    //    - Keep only alphanumeric characters.
    let filtered_chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();

    // 2. Check if the filtered sequence is a palindrome:
    //    We compare the sequence with its reversed version.
    let len = filtered_chars.len();
    if len == 0 {
        // An empty string or a string with no alphanumeric characters is considered a palindrome.
        return true;
    }

    for i in 0..(len / 2) {
        if filtered_chars[i] != filtered_chars[len - 1 - i] {
            return false;
        }
    }

    true
}

