```rust
/// Reverses the elements of a mutable vector in place.
///
/// # Arguments
///
/// * `vec` - A mutable reference to the vector to be reversed.
pub fn reverse_vec<T>(vec: &mut Vec<T>) {
    let len = vec.len();
    // We only need to iterate up to the middle of the vector.
    for i in 0..len / 2 {
        // Swap the element at index `i` with the element at index `len - 1 - i`.
        vec.swap(i, len - 1 - i);
    }
}

fn main() {
    // Example 1: Reversing a vector of integers
    let mut numbers = vec![1, 2, 3, 4, 5];
    println!("Original numbers: {:?}", numbers);
    reverse_vec(&mut numbers);
    println!("Reversed numbers: {:?}", numbers);
    // Expected output: [5, 4, 3, 2, 1]

    println!("--------------------");

    // Example 2: Reversing a vector of strings
    let mut words = vec!["apple", "banana", "cherry", "date"];
    println!("Original words: {:?}", words);
    reverse_vec(&mut words);
    println!("Reversed words: {:?}", words);
    // Expected output: ["date", "cherry", "banana", "apple"]

    println!("--------------------");

    // Example 3: Reversing an empty vector
    let mut empty_vec: Vec<i32> = vec![];
    println!("Original empty vector: {:?}", empty_vec);
    reverse_vec(&mut empty_vec);
    println!("Reversed empty vector: {:?}", empty_vec);
    // Expected output: []
}
```

